static class Program {static void Main(){using var output=new StreamWriter(Console.OpenStandardOutput(),new UTF8Encoding(false),65536);Console.SetOut(output);string line;while((line=Console.ReadLine())!=null){CultureInfo.CurrentCulture=CultureInfo.InvariantCulture;var row=new Row();string error="ok";foreach(var command in line.Split('|')){try{row.Command(command);}catch(Exception e){error=Row.Error(e);break;}}CultureInfo.CurrentCulture=CultureInfo.InvariantCulture;Console.Write(error+"/"+string.Join(";",row.Results)+(row.Results.Count>0?";":"")+"/"+row.Snapshot()+"/"+string.Join(";",row.Events)+(row.Events.Count>0?";":""));Console.WriteLine();}}}
